@startuml

class Ingredient {
  + name : string
  + measuring_unit : string
  + quantity_in_stock : float
}

class Dish {
  + name : string
  + id : int
}

class Table {
  + id : int
  + maximum_amount_of_people : int
}

class Meal {
  + date : date
  + start_time : time
  + end_time : time
}

class Waiter {
  + id : int
  + name : string
  + address : string
  + phone_number : string
}

class Client {
  + tax_identification_number : string
  + name : string
  + address : string
}

class DishUsage {
  + quantity : float
}

Ingredient "1" -- "*" DishUsage : used in
Dish "1" -- "*" DishUsage : part of
Dish "1" -- "*" Meal : consumed in
Meal "1" -- "*" Table : takes place at
Meal "1" -- "0..1" Client : consumed by
Meal "*" -- "1" Waiter : responsible waiter

@enduml

